"""Apply the shared runtime boundary to the world team's single-canvas host."""
from pathlib import Path

ROOT = Path(__file__).resolve().parent
src = (ROOT / 'incoming/world/rive/web/game.js').read_text()
src = src.replace("document.querySelector('canvas')", "document.getElementById('world-canvas')")
import re
src = re.sub(r"fetch\('ducky-land.riv\?v=[^']+'\)", "fetch('ducky-land.riv?v='+Date.now())", src)
src = src.replace("const controls={};for(const key of ['x','y','bg','cap','shades','acc','shoes','city','action','facing','isPlayer'])", "const controls={};for(const key of ['x','y','bg','cap','shades','acc','shoes','city','action','facing','turn','isPlayer','tagVisible'])")
src = src.replace("action:0,facing:1,path:[]", "action:0,facing:1,turn:0,targetTurn:0,path:[]")
src = src.replace("'turn','isPlayer','tagVisible'", "'turn','isPlayer','tagVisible','arrival'")
src = src.replace("city:player?1:i%4,action:0,facing:1,isPlayer", "city:player?1:i%4,action:0,facing:1,turn:360,tagVisible:1,isPlayer")
src = src.replace("turn:360,tagVisible:1,isPlayer", "turn:360,tagVisible:1,arrival:1,isPlayer")
src = src.replace("let viewW=innerWidth", "const updateHooks=[],drawHooks=[],overlayHooks=[];let inputLocked=false;\nlet viewW=innerWidth")
src = src.replace("dpr=Math.min(devicePixelRatio||1,2)", "dpr=(window.game?.controls?.quality==='low'||query.get('quality')==='low')?Math.min(devicePixelRatio||1,1.5):(devicePixelRatio||1)")
src = src.replace("const distance=d.speed*dt,", "const distance=d.speed*dt*(d.player?(window.game?.controls?.strength??1):1),")
src = src.replace("function render(dt){", "function render(dt){\n if(!canvas.getClientRects().length)return;")
src = src.replace("canvas.addEventListener('pointerdown',e=>{canvas.focus", "canvas.addEventListener('worldtap',e=>{canvas.focus")
src = src.replace("toWorld(e.clientX,e.clientY);player.path", "toWorld(e.detail.x,e.detail.y);player.path")
src = src.replace("if(overview)return;", "if(overview||inputLocked)return;")
src = src.replace("const k=e.key.toLowerCase();if(['arrowup'", "if(inputLocked||e.target.closest?.('input,select,button,dialog'))return;const k=e.key.toLowerCase();if(['arrowup'")
src = src.replace("if(!e.repeat&&k==='q')quack(player);", "if(!e.repeat&&k==='q'){if(window.game?.emote)window.game.emote(2);else quack(player);}")
src = src.replace("if(!e.repeat&&k==='e'){player.action=3;player.until=now+4;player.path=[];}", "if(!e.repeat&&k==='e'){if(window.game?.emote)window.game.emote(3);else{player.action=3;player.until=now+6;player.path=[];}}")
src = src.replace("if(d.player){vx=", "if(d.player&&inputLocked)return;\n if(d.player){vx=")
src = src.replace("if(Math.abs(vx)>.03)d.facing=vx<0?-1:1;", "if(Math.abs(vx)>.03)d.facing=vx<0?-1:1;d.targetTurn=Math.atan2(vx,vy)*180/Math.PI;")
src = src.replace("const entities=[...props,...ducks]", "const entities=[...props,...ducks,...drawHooks.flatMap(fn=>fn())]")
src = src.replace("const entities=[...props,...ducks,...drawHooks.flatMap(fn=>fn())]", "const low=window.game?.controls?.quality==='low'||query.get('quality')==='low';const drawnDucks=low?[player,...ducks.filter(d=>!d.player).sort((a,b)=>Math.hypot(a.x-player.x,a.y-player.y)-Math.hypot(b.x-player.x,b.y-player.y)).slice(0,5)]:ducks;\n const entities=[...props,...drawnDucks,...drawHooks.flatMap(fn=>fn())]")
src = src.replace("if(e.sm){e.controls.action.value=e.action;e.controls.facing.value=e.facing;e.sm.advanceAndApply(dt);e.art.advance(dt);}", "if(e.sm){const delta=((e.targetTurn-e.turn+540)%360)-180;e.turn+=delta*(1-Math.exp(-13*dt));e.turn=((e.turn+180)%360+360)%360-180;e.controls.action.value=e.action;e.controls.facing.value=e.facing;if(e.controls.turn)e.controls.turn.value=e.turn+360;e.sm.advanceAndApply(dt);e.art.advance(dt);}else if(e.advance)e.advance(dt);")
src = src.replace("renderer.restore();renderer.flush();runtime.resolveAnimationFrame();", "renderer.restore();for(const fn of overlayHooks)fn(renderer,dt);renderer.flush();runtime.resolveAnimationFrame();")
src = src.replace("for(const d of ducks)stepDuck(d,dt);", "for(const d of ducks)if(!d.managed)stepDuck(d,dt);for(const fn of updateHooks)fn(dt,now);")
src = src.replace("window.game={simulate,runtime,file,world", "window.game={simulate,renderer,ground,createDuck,resize,updateHooks,drawHooks,overlayHooks,quack,\n get inputLocked(){return inputLocked;},set inputLocked(v){inputLocked=!!v;keys.clear();},get now(){return now;},get view(){return {width:viewW,height:viewH,dpr};},runtime,file,world")
src = src.replace("render(){render(0);},ready:true", "render(){render(0);},drawFrame(dt){render(dt);},ready:true")
src = src.replace("drawFrame(dt){render(dt);},ready:true", "drawFrame(dt){render(dt);},captureView(w=1600,h=1000,pixelRatio=2){const saved={viewW,viewH,dpr,width:canvas.width,height:canvas.height,camera:{...camera}};viewW=w;viewH=h;dpr=pixelRatio;canvas.width=w*dpr;canvas.height=h*dpr;camera.x=player.x;camera.y=player.y-100;camera.zoom=1;render(0);const copy=document.createElement('canvas');copy.width=canvas.width;copy.height=canvas.height;copy.getContext('2d').drawImage(canvas,0,0);viewW=saved.viewW;viewH=saved.viewH;dpr=saved.dpr;canvas.width=saved.width;canvas.height=saved.height;Object.assign(camera,saved.camera);render(0);return copy;},ready:true")
src = src.replace("const elapsed=(t-last)/1000||0", "if(document.hidden){last=t;requestAnimationFrame(frame);return;}\n const elapsed=(t-last)/1000||0")
src = src.replace("requestAnimationFrame(frame);\nif(query.has('capture'))", "window.dispatchEvent(new Event('ducky-ready'));requestAnimationFrame(frame);\nif(query.has('capture'))")
src = re.sub(r"fetch\('/__report/boot.json'.*?\);\n", '', src)
src = src.replace("fetch('/__report/error.json',{method:'POST',body:JSON.stringify({error:String(e),stack:e.stack})});", '')
src = re.sub(r"if\(query.has\('capture'\)\)\{.*?\}\n", '', src, flags=re.S)
(ROOT / 'rive/web/game.js').write_text(src)
print('Adapted world runtime with frame, draw, overlay and input boundaries.')
